namespace EasyServiceManager.Services

open System
open System.Text.RegularExpressions

/// <summary>多言語リソースの解決とフォーマットを行うモジュール。</summary>
module Localization =
    /// <summary>対応している言語コードと表示名の配列。</summary>
    let languages =
        [| "ja-JP", "日本語"
           "en-US", "English"
           "zh-CN", "简体中文"
           "zh-TW", "繁體中文"
           "ko-KR", "한국어"
           "vi-VN", "Tiếng Việt"
           "de-DE", "Deutsch"
           "fr-FR", "Français"
           "es-ES", "Español"
           "it-IT", "Italiano"
           "pt-BR", "Português (Brasil)"
           "ru-RU", "Русский" |]

    /// <summary>言語コードを既知の対応コードに正規化します（未対応の場合は None）。</summary>
    let tryNormalizeCode (code: string) : string option =
        if String.IsNullOrWhiteSpace code then None
        else
            let norm = code.Trim().Replace('_', '-').ToLowerInvariant()
            match languages |> Array.tryFind (fun (languageCode, _) -> languageCode.ToLowerInvariant() = norm) with
            | Some (languageCode, _) -> Some languageCode
            | None ->
                match norm with
                | "ja" | "jp" -> Some "ja-JP"
                | "en" | "en-gb" -> Some "en-US"
                | "zh" | "zh-hans" | "zh-cn" | "zh-sg" -> Some "zh-CN"
                | "zh-hant" | "zh-tw" | "zh-hk" | "zh-mo" -> Some "zh-TW"
                | "ko" | "kr" -> Some "ko-KR"
                | "vi" | "vn" -> Some "vi-VN"
                | "de" -> Some "de-DE"
                | "fr" -> Some "fr-FR"
                | "es" -> Some "es-ES"
                | "it" -> Some "it-IT"
                | "pt" | "pt-pt" -> Some "pt-BR"
                | "ru" -> Some "ru-RU"
                | _ ->
                    let prefix = norm.Split('-').[0]
                    languages
                    |> Array.tryFind (fun (languageCode, _) -> languageCode.Split('-').[0].ToLowerInvariant() = prefix)
                    |> Option.map fst

    /// <summary>言語コードを既知の対応コードに正規化します（未対応の場合は ja-JP）。</summary>
    let normalizeCode (code: string) =
        tryNormalizeCode code |> Option.defaultValue "ja-JP"

