    /// <summary>指定された言語コードに対応する配列インデックスを取得します。</summary>
    let private languageIndex code =
        languages
        |> Array.tryFindIndex (fun (languageCode, _) -> languageCode = normalizeCode code)
        |> Option.defaultValue 0

    /// <summary>指定された言語コードで静的テキストを翻訳します。</summary>
    let translate code (text: string) =
        match Map.tryFind text translations with
        | Some values -> values.[languageIndex code]
        | None -> text

