    let private translateSingleText code (text: string) =
        match Map.tryFind text translations with
        | Some values -> values.[languageIndex code]
        | None ->
            match dynamicPatterns |> List.tryPick (fun (pattern, template) ->
                let matched = pattern.Match(text)
                if matched.Success then
                    let args =
                        [| for i in 1 .. matched.Groups.Count - 1 -> box matched.Groups.[i].Value |]
                    Some(template, args)
                else None) with
            | Some(template, args) ->
                let localizedTemplate = translate code template
                try String.Format(localizedTemplate, args)
                with :? FormatException -> text
            | None -> text

    /// <summary>動的プレースホルダーを含むメッセージを指定言語へ翻訳します（改行区切りの複数文にも対応）。</summary>
    let translateText code (text: string) =
        if String.IsNullOrEmpty text then text
        elif text.Contains('\n') && not (Map.containsKey text translations) then
            text.Split('\n')
            |> Array.map (fun line -> translateSingleText code (line.TrimEnd('\r')))
            |> String.concat "\n"
        else
            translateSingleText code text

    /// <summary>翻訳済みテンプレート文字列を書式指定引数でフォーマットします。</summary>
    let format code template (arguments: obj array) =
        try String.Format(translate code template, arguments)
        with :? FormatException -> template
